// Icon lookups. Files in assets/design come from the Figma file; files in
// assets/icons are generated by scripts/extract-icons.mjs for the places where
// the design only has placeholder icons.
import bottle from '../assets/design/icon-bottle.svg'
import coinSmall from '../assets/design/icon-coin-small.svg'
import energy from '../assets/design/icon-energy.svg'
import heart from '../assets/design/icon-heart.svg'
import hunger from '../assets/design/icon-hunger.svg'
import keepWarm from '../assets/design/icon-keep-warm.svg'
import run from '../assets/design/icon-run.svg'
import vikingShield from '../assets/design/icon-viking-shield.svg'
import weightSmall from '../assets/design/icon-weight-small.svg'
import type { SlotId, SlotItem } from '../bridge/types'

const generated = import.meta.glob<string>('../assets/icons/*.svg', {
  eager: true,
  query: '?url',
  import: 'default',
})
const icon = (name: string): string | undefined => generated[`../assets/icons/${name}.svg`]

/** Small white icons used in stat rows and item stat overlays. */
export const statIcons = {
  health: heart,
  stamina: run,
  magicka: icon('stat-magicka')!,
  energy,
  hunger,
  thirst: bottle,
  warmth: keepWarm,
  armor: vikingShield,
  weight: weightSmall,
  value: coinSmall,
  damage: icon('stat-damage')!,
  speed: icon('stat-speed')!,
  count: icon('stat-count')!,
  cost: icon('stat-cost')!,
  magic: icon('stat-magic')!,
  fire: icon('stat-fire')!,
  frost: icon('stat-frost')!,
  shock: icon('stat-shock')!,
  poison: icon('stat-poison')!,
  disease: icon('stat-disease')!,
  ranged: icon('stat-ranged')!,
  skill: icon('stat-skill')!,
} as const

/** Icon for an item stat label sent by the plugin ("Armor", "Damage", ...). */
export function itemStatIcon(label: string): string | undefined {
  return (statIcons as Record<string, string>)[label.toLowerCase()]
}

// What an empty slot shows, and the fallback when an item's own icon key is unknown.
const slotFallback: Record<SlotId, string> = {
  head: 'item-armor-head',
  body: 'item-armor-body',
  hands: 'item-armor-hands',
  feet: 'item-armor-feet',
  leftHand: 'item-shield',
  rightHand: 'item-weapon-sword',
  mask: 'item-mask',
  cloak: 'item-cloak',
  neck: 'item-jewelry-neck',
  ring: 'item-jewelry-ring',
  ranged: 'item-weapon-bow',
  ammo: 'item-ammo-arrow',
}

/** Placeholder art for a slot: by the item's icon key, else by slot. */
export function itemIcon(slot: SlotId, item: SlotItem | null | undefined): string {
  const fromItem = item ? icon(`item-${item.icon}`) : undefined
  // Cloaks and masks arrive as armor-cloak / clothing-mask; show the slot's own art.
  const bySlot = slot === 'cloak' || slot === 'mask' ? icon(slotFallback[slot]) : undefined
  return bySlot ?? fromItem ?? icon(slotFallback[slot])!
}
